const{chromium}=require('playwright'),assert=require('node:assert/strict');(async()=>{const b=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',headless:true,args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:1280,height:900}});await p.goto('file://'+__dirname+'/index.html');const pixels=()=>p.locator('canvas').evaluate(c=>c.toDataURL());const a=await pixels();await p.waitForTimeout(200);assert.notEqual(await pixels(),a);await p.locator('#toggle').click();const frozen=await pixels();await p.waitForTimeout(200);assert.equal(await pixels(),frozen);await p.locator('#time').fill('12');await p.locator('#time').dispatchEvent('input');assert.notEqual(await pixels(),frozen);const before=await pixels();await p.locator('#amplitude').fill('0.2');await p.locator('#amplitude').dispatchEvent('input');assert.notEqual(await pixels(),before);await p.locator('#replay').click();assert.ok(Number(await p.locator('#time').inputValue())<1);await p.setViewportSize({width:375,height:812});assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await p.emulateMedia({reducedMotion:'reduce'});await p.reload();const r=await pixels();await p.waitForTimeout(200);assert.equal(await pixels(),r);console.log('Browser tests passed');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
